---APP---
import Fastify, { type FastifyInstance, type FastifyServerOptions } from 'fastify';

import { registerErrorHandling } from './error-handler.js';
import { usersRoutes } from './routes/users.js';
import { profilesRoutes } from './routes/profiles.js';

export function buildApp(opts: FastifyServerOptions = {}): FastifyInstance {
  const app = Fastify({ logger: false, ...opts });

  // 1. 에러 핸들러 등록 (라우트보다 먼저)
  registerErrorHandling(app);

  // 2. 인증 데코레이터 (라우트 등록 전)
  app.decorateRequest('userId', null);

  // 태스크 14의 서버 기동 대기용. RealWorld 스펙 밖이므로 /api 프리픽스 없음.
  app.get('/health', async () => ({ status: 'ok' }));

  // 3. 라우트 플러그인 등록
  app.register(usersRoutes, { prefix: '/api' });
  app.register(profilesRoutes, { prefix: '/api' });

  return app;
}
---ERRORS---
export type ErrorBody = { errors: Record<string, string[]> };

/**
 * 계약(realworld-error-contract)이 정한 상태코드와 에러 바디를 함께 나르는 예외.
 * hurl이 메시지 문자열을 동등 비교하므로 팩토리 밖에서 문구를 만들지 않는다.
 */
export class ApiError extends Error {
  readonly status: number;
  readonly body: ErrorBody;

  constructor(status: number, errors: Record<string, string[]>) {
    super(`${status} ${JSON.stringify(errors)}`);
    this.name = 'ApiError';
    this.status = status;
    this.body = { errors };
  }

  /** 401 — 인증 헤더 누락, 서명 불일치, 만료 토큰 모두 동일하게 처리한다. */
  static tokenMissing(): ApiError {
    return new ApiError(401, { token: ['is missing'] });
  }

  /** 401 — 사용자 열거 방지를 위해 "없는 이메일"과 "비밀번호 불일치"를 구분하지 않는다. */
  static invalidCredentials(): ApiError {
    return new ApiError(401, { credentials: ['invalid'] });
  }

  static forbidden(resource: 'article' | 'comment'): ApiError {
    return new ApiError(403, { [resource]: ['forbidden'] });
  }

  static notFound(resource: 'article' | 'comment' | 'profile'): ApiError {
    return new ApiError(404, { [resource]: ['not found'] });
  }

  /** 409 — 공식 문서에는 없지만 errors_auth.hurl이 요구한다. */
  static conflict(field: 'username' | 'email'): ApiError {
    return new ApiError(409, { [field]: ['has already been taken'] });
  }

  static blank(...fields: string[]): ApiError {
    const errors: Record<string, string[]> = {};
    for (const field of fields) {
      errors[field] = ["can't be blank"];
    }
    return new ApiError(422, errors);
  }

  static unprocessable(errors: Record<string, string[]>): ApiError {
    return new ApiError(422, errors);
  }
}
---TYPES---
export type ProfileDto = {
  username: string;
  bio: string | null;
  image: string | null;
  following: boolean;
};

/** 인증된 사용자 id, 익명이면 null. optional-auth 라우트에서 사용. */
export type ViewerId = number | null;
---HOOKS---
import type { FastifyRequest, preHandlerHookHandler } from 'fastify';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { verifyToken } from './jwt.js';

declare module 'fastify' {
  interface FastifyRequest {
    userId: number | null;
  }
}

/**
 * RealWorld는 `Authorization: Token <jwt>` 스킴을 쓴다. `Bearer`는 인정하지
 * 않는다(스킴 이름만 대소문자 무시).
 */
function parseToken(req: FastifyRequest): string | null {
  const header = req.headers.authorization;
  if (typeof header !== 'string') return null;

  const [scheme, ...rest] = header.trim().split(/\s+/);
  if (scheme?.toLowerCase() !== 'token' || rest.length !== 1) return null;

  return rest[0] ?? null;
}

/** 토큰이 가리키는 사용자가 실제로 남아 있는지까지 확인한다(삭제된 사용자 방어). */
async function resolveUserId(req: FastifyRequest): Promise<number | null> {
  const token = parseToken(req);
  if (token === null) return null;

  const userId = verifyToken(token);
  if (userId === null) return null;

  const user = await prisma.user.findUnique({ where: { id: userId }, select: { id: true } });
  return user ? user.id : null;
}

/** 헤더 없음 / 스킴 불일치 / 토큰 무효 / 사용자 없음 → 전부 401. */
export const requireAuth: preHandlerHookHandler = async (req) => {
  const userId = await resolveUserId(req);
  if (userId === null) throw ApiError.tokenMissing();
  req.userId = userId;
};

/** 같은 실패 조건에서 401을 던지지 않고 익명(userId = null)으로 강등한다. */
export const optionalAuth: preHandlerHookHandler = async (req) => {
  req.userId = await resolveUserId(req);
};
---SERIALIZER---
import type { ProfileDto } from '../types.js';
import { toProfile } from './profile.js';

/** Prisma에서 include로 가져온 글 레코드. 관계는 호출자가 모두 로드해서 넘긴다. */
export type ArticleWithRelations = {
  slug: string;
  title: string;
  description: string;
  body: string;
  createdAt: Date;
  updatedAt: Date;
  author: { username: string; bio: string | null; image: string | null };
  tags: { order: number; tag: { name: string } }[];
  _count: { favorites: number };
  /** viewer가 좋아요했으면 길이 1, 아니면 0. 익명이면 빈 배열. */
  favorites: unknown[];
  /** viewer가 저자를 팔로우하면 길이 1. 익명이면 빈 배열. */
  authorFollowedBy: unknown[];
};

export type ArticleDto = {
  slug: string;
  title: string;
  description: string;
  body: string;
  tagList: string[];
  createdAt: string;
  updatedAt: string;
  favorited: boolean;
  favoritesCount: number;
  author: ProfileDto;
};

export function toArticle(a: ArticleWithRelations): ArticleDto {
  // 입력 순서(order)를 그대로 보존한다. 알파벳 정렬 금지.
  const tagList = [...a.tags].sort((x, y) => x.order - y.order).map((t) => t.tag.name);

  return {
    slug: a.slug,
    title: a.title,
    description: a.description,
    body: a.body,
    tagList,
    createdAt: a.createdAt.toISOString(),
    updatedAt: a.updatedAt.toISOString(),
    favorited: a.favorites.length > 0,
    favoritesCount: a._count.favorites,
    author: toProfile(a.author, a.authorFollowedBy.length > 0),
  };
}

/** ArticleDto에서 body 키를 제거한 객체. 목록 응답 전용. */
export function toArticleSummary(a: ArticleWithRelations): Omit<ArticleDto, 'body'> {
  const { body: _omit, ...rest } = toArticle(a);
  return rest;
}

export function toArticleResponse(a: ArticleWithRelations): { article: ArticleDto } {
  return { article: toArticle(a) };
}

export function toArticlesResponse(
  items: ArticleWithRelations[],
  articlesCount: number,
): { articles: Omit<ArticleDto, 'body'>[]; articlesCount: number } {
  return { articles: items.map(toArticleSummary), articlesCount };
}
export { toUserResponse, type UserDto, type UserRecord } from './user.js';
export { toProfile, toProfileResponse, type ProfileRecord } from './profile.js';
export {
  toArticle,
  toArticleSummary,
  toArticleResponse,
  toArticlesResponse,
  type ArticleDto,
  type ArticleWithRelations,
} from './article.js';
export {
  toComment,
  toCommentResponse,
  toCommentsResponse,
  type CommentDto,
  type CommentWithRelations,
} from './comment.js';

