import type { FastifyPluginAsync } from 'fastify';

import { prisma } from '../db.js';
import { ApiError } from '../errors.js';
import { requireAuth, optionalAuth } from '../auth/hooks.js';
import { toProfile, toProfileResponse } from '../serializers/index.js';
import { isFollowing } from '../services/follow.js';

type UsernameParams = { username: string };

/** 대상 프로필 조회. 없으면 404 `{"errors":{"profile":["not found"]}}`. */
async function findProfileOr404(username: string) {
  const user = await prisma.user.findUnique({
    where: { username },
    select: { id: true, username: true, bio: true, image: true },
  });
  if (user === null) throw ApiError.notFound('profile');
  return user;
}

export const profilesRoutes: FastifyPluginAsync = async (app) => {
  app.get<{ Params: UsernameParams }>(
    '/profiles/:username',
    { preHandler: optionalAuth },
    async (req) => {
      const target = await findProfileOr404(req.params.username);
      // 자기 자신도 Follow 레코드가 없으므로 자연히 following: false.
      const following = await isFollowing(req.userId, target.id);
      return toProfileResponse(toProfile(target, following));
    },
  );

  app.post<{ Params: UsernameParams }>(
    '/profiles/:username/follow',
    { preHandler: requireAuth },
    async (req) => {
      const target = await findProfileOr404(req.params.username);
      // 멱등: 이미 팔로우 중이어도 200. upsert의 update는 의도적으로 빈 객체.
      await prisma.follow.upsert({
        where: { followerId_followedId: { followerId: req.userId!, followedId: target.id } },
        create: { followerId: req.userId!, followedId: target.id },
        update: {},
      });
      return toProfileResponse(toProfile(target, true));
    },
  );

  app.delete<{ Params: UsernameParams }>(
    '/profiles/:username/follow',
    { preHandler: requireAuth },
    async (req) => {
      const target = await findProfileOr404(req.params.username);
      // 멱등: deleteMany는 0건 삭제여도 예외를 던지지 않는다.
      await prisma.follow.deleteMany({
        where: { followerId: req.userId!, followedId: target.id },
      });
      return toProfileResponse(toProfile(target, false));
    },
  );
};
