const MAX_BASE_LENGTH = 60;

/** 제목을 URL-safe한 base 문자열로. 비ASCII만으로 이뤄진 제목이면 'article'로 대체한다. */
function slugifyTitle(title: string): string {
  const base = title
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, MAX_BASE_LENGTH)
    .replace(/-+$/, '');

  return base || 'article';
}

/**
 * `slugify(title) + '-' + <짧은 랜덤 문자열>`.
 * 동일 제목의 글 2건이 서로 다른 slug를 가져야 하므로 접미사는 항상 붙인다.
 * 그래도 충돌할 수 있으므로 호출자는 unique 위반 시 재호출한다(routes/articles.ts).
 */
export function makeSlug(title: string): string {
  const suffix = Math.random().toString(36).slice(2, 10);
  return `${slugifyTitle(title)}-${suffix}`;
}

